function CatHouseCultivationGetCatPopup:__delete()
    if not isNull(self.enterGo) then
        KTool.SafeDelete(self.enterGo.gameObject)
        if not isNull(self.startLoader) then
            self.startLoader:Release(true)
            self.startLoader = nil
        end
        self.enterGo = nil
    end

    if not isNull(self.timeLineGo) then
        KTool.SafeDelete(self.timeLineGo.gameObject)
        if not isNull(self.timeLineLoader) then
            self.timeLineLoader:Release(true)
            self.timeLineLoader = nil
        end
        self.timeLineGo = nil
    end

    if not isNull(self.endGo) then
        KTool.SafeDelete(self.endGo.gameObject)
    end

    if self.oldShowLoadedScenesState then
        KTool.SetActive(self.oldShowLoadedScenesState.gameObject, true)
    end
    self.oldShowLoadedScenesState = nil
end

function CatHouseCultivationGetCatPopup:Awake()
    self.catShareCloseEvent = Events.AddListener(Constants.EventNames.PreDownloadCatShareClose, Bind(self, self.CatShareCloseEventHandler))
    self:InitData()
    local parentTrans = UIModule.RootCanvas.transform.parent.transform
    local sceneRoot = parentTrans:Find("DownloadScene")
    if sceneRoot then
        KTool.SetActive(sceneRoot.gameObject, false)
    end
end

function CatHouseCultivationGetCatPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local parentTrans = UIModule.RootCanvas.transform.parent.transform
        local sceneRoot = parentTrans:Find("DownloadScene")
        self.oldShowLoadedScenesState = sceneRoot
        if sceneRoot then
            KTool.SetActive(sceneRoot.gameObject, false)
        end
        if self.viewType == ViewType.Egg2Baby then
            KTool.SetActive(self.Root.gameObject, true)
            local catHouseMgr = CatHouseMgr:GetInstance()
            while catHouseMgr:GetSceneCo(SceneId) ~= nil do
                cs_coroutine.yield_return()
            end
            SceneManagementIns:SetActive(SceneId, true)
            -- cs_coroutine.yield_return()
            ---@type SceneInstance
            local sceneInstance = SceneManagementIns:GetSceneInstance(SceneId)
            local cameraObject = sceneInstance:GetCacheObjectByName("Main Camera")
            KTool.GetOrAddComponent(cameraObject, typeof(URPBaseCamera))
            ---------------------
            --- 刷新UI

            CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_huode)
            blocker:AddCondition("CatHouseCultivationGetCatPopup")
            cs_coroutine.start(function()
                self:FreshUI()
                self:ShowCatInfo()

                blocker:RemoveCondition("CatHouseCultivationGetCatPopup")
            end)
        elseif self.viewType == ViewType.OpenBlindBox or self.viewType == ViewType.PreDownload then
            ---@type SceneInstance
            local sceneInstance = SceneManagementIns:GetSceneInstance(SceneId)
            sceneInstance:Enable()
            self.controller.IsCameraState = false
            KTool.SetActive(URPCameraController.mainCamera, false)
            self:FreshUI()
        end

    end))
    return coWait
end

function CatHouseCultivationGetCatPopup:ShowCatInfo()
    KTool.SetActive(self.Root.gameObject, true)
    self:FreshCatDataInfo(self.catData)
    self:SetBtnShareAction()
end

function CatHouseCultivationGetCatPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local node = UIModule.RootCanvas.transform:Find("CatHousDataDetailsNode")
        if not isNull(node) then
            KTool.SafeDelete(node.gameObject)
        end
        ---@type Engine.Lib.BehaviourAction
        local behaviorAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourActionType)
        behaviorAction.LateUpdateAction = nil
        ---@type SceneInstance
        local sceneInstance = SceneManagementIns:GetSceneInstance('21')
        if sceneInstance then
            sceneInstance:Disable()
        end
        local parentTrans = UIModule.RootCanvas.transform.parent.transform
        local sceneRoot = parentTrans:Find("DownloadScene")
        if sceneRoot then
            KTool.SetActive(sceneRoot.gameObject, true)
        end
        Events.RemoveListener(Constants.EventNames.PreDownloadCatShareClose, self.catShareCloseEvent)

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function CatHouseCultivationGetCatPopup:InitData()
    local parameters = self.controller.Argument.parameters
    local viewType = parameters.viewType
    local playerCatId = parameters.playerCatId
    local blindBoxId = parameters.blindBoxId
    local isUnlockCardSill = checkBool(parameters.isUnlockCardSill)
    local geneId = parameters.geneId
    local genes = parameters.genes
    local isNew = parameters.isNew
    if viewType == ViewType.PreDownload then
        self.isNew = isNew
        self.geneId = geneId
        self.catData = self:InitPreDownloadCatData(geneId, genes)
    else
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        self.catData = component:GetCatDataById(playerCatId)
    end
    self.viewType = viewType
    self.blindBoxId = blindBoxId
    self.isUnlockCardSill = isUnlockCardSill
end

---初始化预下载猫球数据
function CatHouseCultivationGetCatPopup:InitPreDownloadCatData(geneId, genes)
    ---@type CatHouseCatDataVo
    local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
    local catId = "101"
    ---创建新的猫
    if catHouseCatDataVo.kind == ConstantsCatHouse.ScreenCatDataType.Combination then
        ---组合
        ---@type CatHouseHeritableVo
        local heritableVo = CatHouseMgr:GetInstance():GetHeritableVoByRefId(catHouseCatDataVo.id)
        catId = table.takeFirst(heritableVo.catId)
    elseif catHouseCatDataVo.kind == ConstantsCatHouse.ScreenCatDataType.Variation then
        ---@type CatHouseHeritableVo
        local heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(catHouseCatDataVo.id)
        catId = table.takeFirst(heritableVo.catId)
    end
    local genesId = {}
    local t = parse_strings(genes)
    for i, v in pairs(t) do
        table.insert(genesId, checkNumber(v))
    end
    local catData = {
        age = ConstantsCatHouse.BornType.Adult,
        catId = catId,
        genes = genesId
    }
    return catData
end

