function CatHouseCultivationGetCatPopup:LoadCatEgg(parent)
    local catId = self.catData.catId
    ---@type CatHouseCatVo
    local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", catId)
    local assetPath = string.format("Arts/Prefab_cat/Prefab_catparts/%s.prefab", catHouseCatVo.catEgg)
    local go = GameUtils.LoadBundleAsync(assetPath, parent, false, true)
    if isNull(go) then
        return
    end
    ---@type UnityEngine.Transform
    local transform = go.transform
    transform.localRotation = Quaternion.identity
    transform.localPosition = Vector3.zero
    transform.localScale = Vector3.one
    self.enterGo = go
end

function CatHouseCultivationGetCatPopup:LoadHand(parent)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local isFemale = not isNull(playerComponent) and playerComponent.playerDojo and (checkInt(playerComponent.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE)
    local assetPath = isFemale and "Arts/Prefab_home/Prefab_runtime_item/100_hand_f.prefab" or "Arts/Prefab_home/Prefab_runtime_item/100_hand_m.prefab"
    --local blindBoxId = self.blindBoxId
    -----@type CatHouseBlindBoxGoodsVo
    --local blindBoxGoodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(blindBoxId)
    --local assetPath = blindBoxGoodsVo.boxPrefab
    local go = GameUtils.LoadBundleAsync(assetPath, parent, false, true)
    if isNull(go) then
        return
    end
    ---@type UnityEngine.Transform
    local transform = go.transform
    transform.localRotation = Quaternion.identity
    transform.localPosition = Vector3.zero
    transform.localScale = Vector3.one
    self.enterGo = go
end

function CatHouseCultivationGetCatPopup:LoadCat(parent, enableAni)
    local catData = self.catData
    local catHouseMgr = CatHouseMgr:GetInstance()
    catHouseMgr:LoadCatModelAsync(catData.age, catData.catId, false, catData.genes, nil, function(go)
        ---@type UnityEngine.Transform
        local transform = go.transform
        transform.localRotation = Quaternion.identity
        transform.localPosition = Vector3.zero
        transform.localScale = Vector3.one
        self.catAnimancer = KTool.GetComponent(go, typeof(CS.Animancer.NamedAnimancerComponent))
        self.catAnimancer.enabled = enableAni == true

        KTool.SetParent(go.gameObject, parent, false)
        self.endGo = go
    end)
end

---丢猫球过程中的音效
