function CatHouseCultivationGetCatPopup:SetMusic(tlIndex)
    for i, v in pairs(MusicTL) do
        if i == tlIndex then
            CriWareUtils.PlaySeById(v)
        else
            CriWareUtils.StopById(v)
        end
    end
end

function CatHouseCultivationGetCatPopup:LoadAndPlayTimeLine()
    if self.viewType == ViewType.OpenBlindBox or self.viewType == ViewType.PreDownload then
        local isStop = false
        local time = GameUtils.ShowBlackOverlay(nil, function()
            while not isStop do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end)
        self:StartLoadAndPlayTimeLine()
        coroutine.yield(Yielders.GetWaitForSeconds(time))
        isStop = true
    else
        self:StartLoadAndPlayTimeLine()
    end
end

function CatHouseCultivationGetCatPopup:StartLoadAndPlayTimeLine()
    local assetPath = ViewType2TimeLine[self.viewType]
    local go = GameUtils.LoadBundleAsync(assetPath, nil, false, true)
    if isNull(go) then
        return
    end
    if self.viewType == ViewType.Egg2Baby then
        local enterParentName, endParentName = SafeUnpack(ViewType2ParentName[self.viewType])
        self:LoadCatEgg(go.transform:Find(enterParentName).gameObject)
        self:LoadCat(go.transform:Find(endParentName).gameObject, true)
    else
        self.director = KTool.GetComponent(go.gameObject, PlayableDirectorType)
        self.timelineNotificationReceiver = KTool.GetOrAddComponent(go.gameObject, typeof(CS.TimelineNotificationReceiver))
        self.__ProcessNotify = Bind(self, self.ProcessNotify)
        self.timelineNotificationReceiver:CustomOnNotify("+", self.__ProcessNotify)
        self:LoadHand(go.gameObject)
        self:LoadCat(go.gameObject)
        CatHouseMgr:GetInstance():SetBlindBoxNode(go.gameObject)
        local cam = KTool.GetOrAddComponent(go.transform:Find("throw_part03_cam/cam").gameObject, typeof(Camera))
        URPCameraController:InitCameraStack(cam)
        CatHouseMgr:GetInstance():SetCatNodeActive(false)
        --KTool.SetActive(URPCameraController.mainCamera, false)
        --
        self:SetMusic(1)
        local touchSpine = go.transform:Find("Canvas/SkeletonGraphic (button)")
        local touchAnim = touchSpine.transform:Find("AnimRoot")
        self.TouchRegion.onSingleFingerDown:AddListener(function(position)
            if isNull(position) then
                return
            end
            if self.enableLongTouch then
                self:SetMusic(2)
                CfUtils.PlaySpine(touchSpine, "Openning")
                KTool.SetActive(touchAnim.gameObject, true)
            end
        end)
        self.TouchRegion.onSingleFingerUp:AddListener(function(position)
            if isNull(position) then
                return
            end
            CriWareUtils.StopById(MusicTL[2])
            CfUtils.PlaySpine(touchSpine, "Idle")
            KTool.SetActive(touchAnim.gameObject, false)
        end)

        self.TouchRegion.onLongPress:AddListener(function()
            print("longPress=============>>")
            if self.enableLongTouch then
                self.enableLongTouch = false
                self.director:Evaluate()
                self:Resume()
            end
        end)
    end
    ---@type UnityEngine.Playables.PlayableDirector
    local director = go.gameObject:GetComponent(PlayableDirectorType)
    director.extrapolationMode = DirectorWrapMode.Hold
    --- 1. bind time line
    local list = support.new_list(typeof(CS.UnityEngine.Playables.PlayableBinding))
    list:AddRange(director.playableAsset.outputs)
    local trackNames = ViewType2TrackNameList[self.viewType]
    local trackName2Go = {
        [trackNames[1]] = self.enterGo.gameObject,
        [trackNames[2]] = self.endGo.gameObject,
    }
    if self.viewType == ViewType.OpenBlindBox or self.viewType == ViewType.PreDownload then
        trackName2Go[trackNames[3]] = self.endGo.gameObject:GetComponent(typeof(Animator))
    end
    local cached = {}
    for i = 0, list.Count - 1 do
        local object = trackName2Go[list[i].streamName]
        if object then
            local sourceObject = list[i].sourceObject
            director:SetGenericBinding(sourceObject, object)
            table.insert(cached, sourceObject)
        end
    end

    list:Clear()

    --- 2. play time line
    director:Play()


    --- 3. stop time line
    --director:Stop()

    --- 4. clear cache
    self.timeLineGo = go
    if self.viewType == ViewType.Egg2Baby then
        cs_coroutine.yield_return()
        coroutine.yield(Yielders.GetWaitForSeconds(director.duration))
        cs_coroutine.yield_return()

        local animancerState = self.catAnimancer:TryPlay("touch3", 1.5)
        if not isNull(animancerState) then
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animancerState.Length))
            self.catAnimancer:TryPlay("idle")
        end

        director.time = director.duration
        for i = 1, #cached do
            director:ClearGenericBinding(cached[i])
        end
        local abs = math.abs
        self.TouchRegion.onSingleFingerDrag:AddListener(function(delta)
            if isNull(self.endGo) then
                return
            end
            local y = delta.y
            local x = delta.x
            if abs(x) < abs(y) then
                return
            end
            local direction = x < 0 and 1 or -1
            local eulerAngles = Vector3.New(0, 1, 0)
            eulerAngles.y = eulerAngles.y * direction * abs(x)
            self.endGo.transform:Rotate(eulerAngles)
        end)

        self:SetBtnTouchRegion()

    elseif self.viewType == ViewType.OpenBlindBox then
        ---@type Engine.Lib.BehaviourAction
        local behaviorAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourActionType)
        behaviorAction.LateUpdateAction = Bind(self, self.LateUpdate)
    elseif self.viewType == ViewType.PreDownload then
        ---@type Engine.Lib.BehaviourAction
        local behaviorAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourActionType)
        behaviorAction.LateUpdateAction = Bind(self, self.LateUpdate)
    end


    ---TODO 改成获取Animancer 来播放动画
    -----@type UnityEngine.Animator
    -- local animator = KTool.GetComponent(self.endGo.gameObject, typeof(Animator))
    -- if animator then
    --     animator:SetInteger("touch", 3)
    --     coroutine.yield(Yielders.GetWaitForSeconds(1.1))
    --     animator:SetInteger("touch", 0)
    -- end

    --if self.viewType == ViewType.Egg2Baby then
    --    local abs = math.abs
    --    self.TouchRegion.onSingleFingerDrag:AddListener(function(delta)
    --        if isNull(self.endGo) then return end
    --        local y = delta.y
    --        local x = delta.x
    --        if abs(x) < abs(y) then
    --            return
    --        end
    --        local direction = x < 0 and 1 or -1
    --        local eulerAngles = Vector3.New(0, 1, 0)
    --        eulerAngles.y = eulerAngles.y * direction * abs(x)
    --        self.endGo.transform:Rotate(eulerAngles)
    --    end)
    --elseif self.viewType == ViewType.OpenBlindBox then
