end

function CatHouseCultivationGetCatPopup:SetBtnShareAction()
    SetButtonAction(self.BtnShare, function()
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_button_share)
        if self.viewType == ViewType.OpenBlindBox or self.viewType == ViewType.Egg2Baby then
            local currentCatData = self.catData
            GameUtils.ShareScreenShot({
                prefabPath = 'Prefabs/CatHouse/Interaction/CatHouseCatShareShow.prefab',
                prefabArgs = currentCatData,
                --isWaitCompleted = true,
                finishCB = function(filePath)
                    GachaponUtils.OpenDialogAction(Constants.UITypeIds.CommonSharePreviewDialog, {
                        filePath = filePath,
                        shareType = Constants.ShareType.CAT_BABY_BIRTH,
                    })
                end
            })

        end

    end)
end

function CatHouseCultivationGetCatPopup:SetBtnTouchRegion()
    SetButtonAction(self.TouchRegion.gameObject, function()
        if not isNull(self.enterGo) then
            KTool.SetActive(self.enterGo.gameObject, false)
        end
        if not isNull(self.timeLineGo) then
            KTool.SetActive(self.timeLineGo.gameObject, false)
        end
        if not isNull(self.endGo) then
            KTool.SetActive(self.endGo.gameObject, false)
        end
        KTool.SetActive(self.controller.gameObject, false)
        UIModule.BackDialog()
        if self.viewType ~= ViewType.Egg2Baby then
            CatHouseMgr:GetInstance():SetCatNodeActive(true)
        end
        KTool.SetActive(URPCameraController.mainCamera, true)
        ---@type CatHouseComponent
        local component = GameUtils.CreateEntityWithComponent(Constants.CatHouseEntityId, ECSComponentType.Constants.CatHouseComponent)
        if component then
            if self.isUnlockCardSill then
                local t = component:GetMergeSkillWithBorn()
                Events.Broadcast(CAT_GET_POPUP_FINISH, t)
            else
                --component:CheckMergeSkillByTypeOrGene(1001, self.catData.catId)
                local data = component:GetPopData()
                if data then
                    Events.Broadcast(CAT_GET_POPUP_FINISH, data)
                end
            end
        end
    end)
end

function CatHouseCultivationGetCatPopup:FreshCatDataInfo(catData)
    ---@type CatHouseCatDataInfo
    local env = CfUtils.GetLuaScr(self.LeftPanel, CatHouseCatDataInfoEnvPath)
    if isNull(env) then
        return
    end
    env:FreshUI(catData, true)


end

function CatHouseCultivationGetCatPopup:ProcessNotify(origin, notification, context)
    local notifyType = notification:GetType()
    print("ProcessNofity", notifyType)
    if notifyType == typeof(CS.Game.Native.QTE.QTELongTouchMarker) then
        --self.touchRect = notification.touchRect:Resolve(self.director)
        self:Pause()
        self.enableLongTouch = true
    elseif notifyType == typeof(CS.Game.Native.QTE.QTESoundPlayMarker) then
        self:SetMusic(3)
    end
end

function CatHouseCultivationGetCatPopup:Pause()
    self.isPaused = true
    self.director:Pause()
end

function CatHouseCultivationGetCatPopup:Resume()
    self.isPaused = false
    self.director:Resume()
end

function CatHouseCultivationGetCatPopup:LateUpdate(dt)
    if isNull(self.director) then
        return
    end
    if self.isPaused then
        self.director:Evaluate()
    end
    if self.director.duration <= self.director.time then
        print("OnFinish", self.director.duration, self.director.time)
        if self.viewType == ViewType.PreDownload then
            UIModule.OpenDialog({ id = Constants.UITypeIds.PreDownloadCatShareDialog, parameters = { geneId = self.geneId, isNew = self.isNew } },
                    { { id = Constants.UITypeIds.PreDownloadCatMainDialog } },
                    false
            )
            CfUtils.SetTopActive(true)
        else
            if self.viewType == ViewType.OpenBlindBox then
                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_manghehuode)
            end
            self:ShowCatInfo()
        end
        self:SetBtnTouchRegion()
        ---@type Engine.Lib.BehaviourAction
        local behaviorAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourActionType)
        behaviorAction.LateUpdateAction = nil
    end
end

function CatHouseCultivationGetCatPopup:CatShareCloseEventHandler()
    if not isNull(self.enterGo) then
        KTool.SetActive(self.enterGo.gameObject, false)
    end
    if not isNull(self.timeLineGo) then
        KTool.SetActive(self.timeLineGo.gameObject, false)
    end
    if not isNull(self.endGo) then
        KTool.SetActive(self.endGo.gameObject, false)
    end
    KTool.SetActive(self.controller.gameObject, false)
    if self.viewType ~= ViewType.Egg2Baby then
        CatHouseMgr:GetInstance():SetCatNodeActive(true)
    end
    KTool.SetActive(URPCameraController.mainCamera, true)
    UIModule.CloseDialog(self.controller)
end

